const fs = require('fs');

let ar = [];
let solved = 0;

function moveStatues(v) {
    for (let i = 0; i < v.length; i++) {
        v[i][0]++;
    }
}

function checkOnStatue(i, j, v) {
    for (let k = 0; k < v.length; k++) {
        if (i === v[k][0] && j === v[k][1]) {
            return 1;
        }
    }
    return 0;
}

function dfs(i, j, v, used) {
    // Deep clone to simulate pass-by-value semantics of C++ vectors
    v = v.map(statue => [...statue]);
    used = used.map(row => [...row]);

    if (i < 0 || j < 0 || j >= 8 || i >= 8 || used[i][j]) {
        return 0;
    }
    if (checkOnStatue(i, j, v)) {
        return 0;
    }
    if (i === 0 && j === 7) {
        solved = 1;
        return 1;
    }

    moveStatues(v);
    if (checkOnStatue(i, j, v)) {
        return 0;
    }

    let x = 0;
    used[i][j] = 1;

    // Since we cloned at the start, v and used are local copies.
    // We can pass them directly to recursive calls; they will clone again upon entry.
    x = Math.max(dfs(i - 1, j, v, used), x); if (solved) return 1;
    x = Math.max(dfs(i, j + 1, v, used), x); if (solved) return 1;
    x = Math.max(dfs(i, j - 1, v, used), x); if (solved) return 1;
    x = Math.max(dfs(i + 1, j, v, used), x); if (solved) return 1;
    x = Math.max(dfs(i + 1, j + 1, v, used), x); if (solved) return 1;
    x = Math.max(dfs(i + 1, j - 1, v, used), x); if (solved) return 1;
    x = Math.max(dfs(i - 1, j + 1, v, used), x); if (solved) return 1;
    x = Math.max(dfs(i - 1, j - 1, v, used), x); if (solved) return 1;
    x = Math.max(dfs(i, j, v, used), x); if (solved) return 1;

    return x;
}

function main() {
    const input = fs.readFileSync('/dev/stdin', 'utf8').trim().split('\n');

    const used = Array(8).fill().map(() => Array(8).fill(0));
    const v = [];

    for (let i = 0; i < 8; i++) {
        const str = input[i];
        ar.push(str);
        for (let j = 0; j < 8; j++) {
            if (str[j] === 'S') {
                v.push([i, j]);
            }
        }
    }

    let x = 0;
    x = dfs(7, 0, v, used);
    if (x === 1) { console.log("WIN"); return; }

    x = dfs(6, 0, v, used);
    if (x === 1) { console.log("WIN"); return; }

    x = dfs(6, 1, v, used);
    if (x === 1) { console.log("WIN"); return; }

    x = dfs(7, 1, v, used);
    if (x === 1) { console.log("WIN"); return; }
    else {
        console.log("LOSE");
    }
}

main();

